CREATE TABLE IF NOT EXISTS intelligence_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES assets(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE CASCADE, model_version text NOT NULL DEFAULT 'OV-AI-V1', state text NOT NULL DEFAULT 'insufficient_data', trust_score numeric(6,2), evidence_score numeric(6,2), verification_score numeric(6,2), risk_score numeric(6,2), economics_score numeric(6,2), overall_score numeric(6,2), facts jsonb NOT NULL DEFAULT '[]'::jsonb, evidence_claims jsonb NOT NULL DEFAULT '[]'::jsonb, inferences jsonb NOT NULL DEFAULT '[]'::jsonb, assumptions jsonb NOT NULL DEFAULT '[]'::jsonb, conflicts jsonb NOT NULL DEFAULT '[]'::jsonb, missing_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, recommendations jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());